import{_ as t,o as a,c as r,ag as i}from"./chunks/framework.gmyryY1Z.js";const u=JSON.parse('{"title":"Architecture Evolution Overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/evolution/index.md","filePath":"en/evolution/index.md","lastUpdated":null}'),o={name:"en/evolution/index.md"};function n(s,e,l,c,p,d){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="architecture-evolution-overview" tabindex="-1">Architecture Evolution Overview <a class="header-anchor" href="#architecture-evolution-overview" aria-label="Permalink to &quot;Architecture Evolution Overview&quot;">​</a></h1><p>Fast Vue3 underwent a complete architectural evolution from <strong>Polyrepo (single repo)</strong> to <strong>Monorepo (multi-package repo)</strong>.</p><h2 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2022 ~ 2024          2025 Q1              2025 Q2 ~ present</span></span>
<span class="line"><span>────────────        ────────────         ────────────────</span></span>
<span class="line"><span> Polyrepo phase       Archive phase         Monorepo phase</span></span>
<span class="line"><span> Single app           polyrepo branch       main branch rebuilt</span></span>
<span class="line"><span> Vite + Vue3          History preserved     Multi-app platform</span></span>
<span class="line"><span> Standardization      Archived              5 UI ecosystems</span></span></code></pre></div><h2 id="two-architectures-preserved" tabindex="-1">Two Architectures Preserved <a class="header-anchor" href="#two-architectures-preserved" aria-label="Permalink to &quot;Two Architectures Preserved&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Branch</th><th>Architecture</th><th>Description</th></tr></thead><tbody><tr><td><code>polyrepo</code></td><td>Polyrepo</td><td>Historical legacy architecture, archived</td></tr><tr><td><code>main</code></td><td>Monorepo</td><td>New architecture, actively maintained</td></tr></tbody></table><p>The <code>polyrepo</code> branch is kept as a historical reference and receives no new feature development. All new work happens on <code>main</code>.</p><h2 id="why-migrate" tabindex="-1">Why Migrate <a class="header-anchor" href="#why-migrate" aria-label="Permalink to &quot;Why Migrate&quot;">​</a></h2><p>Core pain points of the Polyrepo phase:</p><ol><li><strong>Version fragmentation</strong> — All dependency versions scattered in a single <code>package.json</code>, hard to upgrade uniformly</li><li><strong>No code reuse</strong> — Supporting multiple UI frameworks required duplicating the entire project</li><li><strong>Repeated config</strong> — ESLint, TypeScript, Vite configs had to be rewritten for each project</li><li><strong>No package boundaries</strong> — All code mixed under <code>src/</code>, unclear responsibilities</li><li><strong>Poor scalability</strong> — Adding new tech stacks required forking the repository</li></ol><p>Core problems Monorepo solves:</p><ul><li><strong>Unified version management</strong> — pnpm workspace catalog</li><li><strong>Shared infrastructure</strong> — <code>packages/*</code> written once, reused everywhere</li><li><strong>Scalability</strong> — Adding a new UI ecosystem = adding one app in <code>apps/</code></li><li><strong>Clear boundaries</strong> — Each package has a single responsibility with a clear API</li></ul><h2 id="this-section" tabindex="-1">This Section <a class="header-anchor" href="#this-section" aria-label="Permalink to &quot;This Section&quot;">​</a></h2><ul><li><a href="./polyrepo">Polyrepo Historical Architecture</a> — Original structure analysis, technical debt, optimization work</li><li><a href="./monorepo">Monorepo New Architecture</a> — New architecture design, package splitting strategy, key decisions</li><li><a href="./comparison">Architecture Comparison</a> — Pros/cons, use cases, decision rationale</li></ul>`,14)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
